import{_ as a,C as i,o as u,c as l,j as t,a as n,E as s,a2 as o}from"./chunks/framework.BxGh02fV.js";const f=JSON.parse('{"title":"Carte","description":"","frontmatter":{"title":"Carte"},"headers":[],"relativePath":"guide/ontologie.md","filePath":"guide/ontologie.md"}'),g={name:"guide/ontologie.md"};function c(p,e,d,m,v,h){const r=i("Capture");return u(),l("div",null,[e[0]||(e[0]=t("h1",{id:"carte",tabindex:"-1"},[n("Carte "),t("a",{class:"header-anchor",href:"#carte","aria-label":'Permalink to "Carte"'},"​")],-1)),e[1]||(e[1]=t("p",null,[n("Cet écran est la carte de votre projet : ses axes de développement, rangés en couches et reliés entre eux, avec leur avancement calculé depuis le registre. Vous y venez pour voir d'un coup d'œil d'où vient le projet, où il en est et où il va, pour ranger la carte à votre façon, et pour trancher ce que l'agent propose. On l'ouvre par "),t("strong",null,"Carte"),n(", dans le groupe « Pilotage » de la barre latérale.")],-1)),s(r,{name:"ontologie",alt:"L'écran Carte : l'arbre des éléments à gauche, la carte rangée en quartiers le long du fil de conception (① But … ⑦ Capacités réalisées, Périphérie, Hors fil), le dock en bas"}),e[2]||(e[2]=o('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><p>L&#39;écran se lit en deux zones. <strong>En haut, le pilotage</strong> : la version courante ; la pastille <strong>N propositions de l&#39;agent</strong> quand l&#39;agent attend une réponse ; <strong>À traiter</strong> (avec le nombre de points) et <strong>Historique</strong>, qui ouvrent leur panneau à côté de la carte ; <strong>Annuler le rangement de l&#39;agent</strong> quand l&#39;agent vient de ranger la carte ; <strong>Exporter</strong>. <strong>À gauche de la carte, l&#39;arbre des éléments</strong> : toute la structure de la carte affichée, sur toute la hauteur — les zones et sous-groupes d&#39;une disposition, ou les couches et groupes de Personnalisée, chacun avec le nombre de ses cartes. <strong>Sur la carte, le visuel</strong> : en haut, centrés, <strong>Rechercher…</strong>, la lecture (<strong>Passé</strong>, <strong>Présent</strong>, <strong>Cible</strong>) et <strong>Filtres</strong> ; le <strong>dock</strong> en bas, centré — les types d&#39;atomes en icônes (faute de place, quand un panneau est ouvert, ils se replient derrière <strong>Ajouter</strong>), puis <strong>Sélection</strong>, <strong>Groupe (F)</strong>, <strong>Grille</strong>, <strong>Visite</strong> et le choix de <strong>disposition</strong> ; en bas à droite, la mini-carte et le zoom — <strong>−</strong>, le pourcentage (un clic revient à 100 %), <strong>+</strong>, <strong>Tout voir</strong> et <strong>Options d&#39;affichage</strong>. Chaque panneau de droite se ferme par sa croix.</p><p>Sur la carte :</p><ul><li>dans <strong>Personnalisée</strong>, chaque <strong>couche</strong> est un cadre ; un <strong>groupe</strong> est un cadre libre que vous tracez vous-même. Dans une disposition calculée, les cadres sont des <strong>zones</strong> arrondies, une par étape du fil, et la couche n&#39;y est plus qu&#39;un sous-groupe discret ;</li><li>chaque <strong>atome</strong> est une carte : l&#39;entête, marqué de l&#39;icône de son type, est coloré selon ce type (but, acteur, capacité, composant, module, interface, entité de données, flux, contrainte, décision, risque, jalon), avec sa priorité ; la <strong>nature technique</strong> d&#39;un composant (écran, service, API…) se lit dans un badge, avec son icône, à côté de son type ; en pied, sa <strong>révision</strong> (<strong>À réviser</strong>, <strong>Cadré</strong>, <strong>Validé</strong>) et son <strong>avancement</strong>, calculé depuis les épics, stories, tâches et évolutions de son pipe. Ce qui est fait passe en demi-teinte, ce qui est en cours reste plein. Un <strong>▲</strong> signale un point à traiter : un clic dessus l&#39;ouvre ;</li><li>chaque <strong>lien</strong> est une courbe de l&#39;atome source vers l&#39;atome cible, avec son type et sa nature. Ses extrémités se répartissent le long des bords quand plusieurs liens partent du même côté.</li></ul><p><strong>Filtres</strong> ouvre cinq listes — <strong>Couche</strong>, <strong>Horizon</strong>, <strong>Avancement</strong>, <strong>Révision</strong>, <strong>Épic</strong> — et estompe ce qui ne correspond pas, sans rien cacher : la carte garde sa forme. Chaque filtre actif devient une pastille à côté du bouton ; sa croix le retire, lui seul. Trois lectures répondent chacune à une question, écrite à côté de leurs boutons : <strong>Passé</strong> — « Qu’avons-nous livré ? » (ce qui est fait reste en couleur, avec la version qui l’a livré, « livré en v0.2.47 », ou « fait, non livré ») ; <strong>Présent</strong> — « Qu’est-ce qui avance ? » (ce qui est en cours et ce qui porte une alerte) ; <strong>Cible</strong> — « Où allons-nous ? » (une couleur par horizon, et les <strong>écarts</strong> : visé Maintenant mais pas commencé, ou visé sans aucun travail). Le reste s’efface, grisé. La légende compte chaque entrée ; un clic sur une entrée ne garde qu’elle, un second la retire.</p><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><p>Chaque geste est enregistré aussitôt. <strong>⌘Z</strong> l&#39;annule et <strong>⇧⌘Z</strong> le rétablit, pour tous les gestes de la séance.</p><ul><li><strong>Naviguer</strong> : la molette ou le pincement zooment autour du pointeur ; maintenir <strong>Espace</strong> et glisser déplace la vue ; <strong>⌘0</strong> ou <strong>⇧1</strong> cadre tout (<strong>Tout voir</strong>), <strong>⌘1</strong> revient à 100 % ; les boutons du zoom font de même. Zoom et cadrages glissent en douceur ; tout nouveau geste les interrompt. La mini-carte, au-dessus du zoom, se clique pour recentrer la vue ; cliquer puis glisser la déplace en direct. Vue de loin, chaque zone affiche son nom en grand, en haut à gauche.</li><li><strong>Sélectionner</strong> : un clic sur un élément ouvre son panneau ; <strong>⇧</strong>-clic ajoute à la sélection ; un rectangle tracé sur le fond sélectionne ce qu&#39;il couvre ; <strong>Échap</strong> désélectionne ; <strong>Suppr</strong> retire la sélection, après une confirmation qui nomme ce qui part (« Supprimer 2 atomes et 3 liens ? »), comme toute suppression.</li><li><strong>Ranger</strong> : glissez un atome ou un cadre (un cadre emporte ses atomes) ; un groupe se saisit par son en-tête, son fond ou sa bordure, une zone de disposition par sa bordure. Sélectionné, un cadre montre sa poignée de taille dans le coin bas-droit. L&#39;élément reste là où vous le lâchez. La carte s&#39;accroche à la grille (<strong>Grille</strong>, <strong>⌘&#39;</strong>) et aux bords et centres des autres objets ; des guides magenta l&#39;indiquent, et les <strong>écarts égaux</strong> entre voisins sont cotés. Maintenir <strong>⌥</strong> suspend l&#39;accroche. Déposer un atome dans un groupe l&#39;y range ; dans une couche, change sa couche.</li><li><strong>Choisir une disposition</strong> : le bouton de disposition, au bout du dock, propose <strong>Quartiers</strong>, <strong>Cercles</strong> et <strong>Imbrication</strong>, puis <strong>Personnalisée</strong> et vos dispositions nommées. Les trois premières rangent la carte selon le fil de conception — ① But → ② Capacités → ③ Cibles → ④ Modules → ⑤ Composants → ⑥ Décisions → ⑦ Capacités réalisées, avec la <strong>Périphérie</strong> (risques, contraintes, ressources) et le <strong>Hors fil</strong> (ce qui n&#39;a aucun lien) à part : <strong>Quartiers</strong> en quartiers successifs, <strong>Cercles</strong> en spirale autour des modules, <strong>Imbrication</strong> en boîtes emboîtées (Intention, Solution, Décisions). Un fil pâle, numéroté, relie les étapes. Ces dispositions sont calculées à l&#39;affichage et n&#39;écrivent rien ; votre choix est gardé dans votre profil, il ne change pas la carte des autres.</li><li><strong>Votre travail d&#39;abord</strong> : vos groupes, leurs noms, leurs couleurs et les cartes que vous y avez mises sont <strong>communs à toutes les dispositions</strong>. Quartiers, Cercles et Imbrication rangent chacun de vos groupes d&#39;un bloc, dans l&#39;étape qui porte le plus de ses cartes ; un groupe sans carte va dans <strong>Vos groupes</strong>. Une boîte calculée que vous avez renommée ou colorée garde son nom et sa couleur d&#39;une disposition à l&#39;autre ; quand une disposition n&#39;a pas de boîte équivalente, un bandeau le dit, et rien n&#39;est perdu. Renommer ou colorer un groupe, colorer une carte, créer un groupe s&#39;appliquent partout, quelle que soit la disposition affichée.</li><li><strong>Garder une disposition</strong> : une disposition se <strong>crée</strong>, elle n&#39;écrase jamais rien. Dans une disposition calculée, <strong>Garder cette disposition</strong>, ou simplement déplacer une carte, crée une disposition à vous, « Quartiers retouchée » ; un bandeau le dit, avec <strong>Renommer</strong> et <strong>Annuler</strong>. <strong>Personnalisée</strong> est la disposition du projet, partagée avec l&#39;équipe : elle ne change que par un geste fait dans Personnalisée. Vos dispositions nommées sont à vous seul (elles ne partent pas dans le dépôt) ; le sélecteur les renomme, les duplique ou les supprime, et une suppression s&#39;annule depuis son bandeau. Une carte qu&#39;une disposition ne place pas encore y arrive près de ses voisins, marquée <strong>à placer</strong>, jusqu&#39;à ce que vous la posiez.</li></ul>',8)),s(r,{name:"ontologie-dispositions",alt:"Le sélecteur de dispositions : Quartiers, Cercles et Imbrication calculées ; Personnalisée, une disposition à soi et la proposition de l'agent, marquée « Proposée par l'agent »"}),e[3]||(e[3]=t("ul",null,[t("li",null,[t("strong",null,"La proposition de l'agent"),n(" : quand vous demandez à l'agent de ranger la carte, il crée sa propre disposition, « Proposition de l'agent — <date> », marquée « Proposée par l'agent » dans le sélecteur. Il s'inspire de vos couleurs et de vos groupes, mais ne touche jamais à votre travail ni à Personnalisée. Un bandeau dit ce qu'il propose (groupes, couleurs, rattachements) ; une carte qu'il range dans un de vos groupes est marquée "),t("strong",null,"suggestion"),n(". "),t("strong",null,"Garder tout"),n(" fait passer la proposition dans votre travail ; "),t("strong",null,"Garder"),n(", dans l'inspecteur, ne garde qu'un élément ; ⌘Z annule. "),t("strong",null,"Supprimer la proposition"),n(" la retire.")])],-1)),s(r,{name:"ontologie-proposition-agent",alt:"Une proposition de l'agent : le bandeau dit ce qu'elle propose, avec Garder tout et Supprimer la proposition ; son groupe Facturation à venir est sélectionné, et l'inspecteur propose de le garder"}),e[4]||(e[4]=o("<ul><li><strong>Décrire un groupe</strong> : dans le panneau d&#39;un groupe, <strong>Métadonnées</strong> liste ce que le groupe porte ; le bouton <strong>+</strong> ouvre un tableau où chaque ligne choisit une métadonnée comprise par Effortless, puis sa valeur parmi ce que le projet contient : un <strong>épic</strong>, une <strong>story</strong>, une <strong>décision</strong>, une <strong>évolution</strong>, une <strong>stack</strong>, un <strong>document</strong>, un <strong>horizon</strong> ou une <strong>couche</strong>. La fiche à droite dit à quoi sert chaque métadonnée, à quoi elle se lie, ce qu&#39;en font Effortless et l&#39;agent. Rien ne s&#39;invente : une clé inconnue est refusée ; une clé ancienne non comprise est gardée et signalée. Le groupe affiche ses métadonnées au bout de son en-tête (l&#39;état de l&#39;épic cité, par exemple), et une carte créée dans le groupe en reçoit la couche, la stack, l&#39;horizon et la citation du travail dans son pipe ; le bandeau le dit.</li></ul>",1)),s(r,{name:"ontologie-metadonnees",alt:"La modale des métadonnées du groupe Pôle planning : un épic et une stack choisis dans les listes du projet, et la fiche qui explique la clé"}),e[5]||(e[5]=o("<ul><li><strong>Visiter</strong> : <strong>Visite</strong> parcourt le fil étape par étape (<strong>Précédent</strong>, <strong>Suivant</strong>, <strong>Quitter</strong>, ou <strong>Échap</strong>). L&#39;étape est cadrée et entourée d&#39;un halo, le reste s&#39;estompe ; un cartouche dit ce que l&#39;étape apporte au raisonnement et, pour chaque carte, ce qu&#39;elle relie en amont (une capacité, le but qu&#39;elle sert). À l&#39;étape ⑥, chaque décision rattachée se lit dans le registre, en direct : la décision, son <strong>motif</strong>, les <strong>alternatives écartées</strong> (barrées, en fantôme) et les forces de la périphérie qui ont pesé ; ce qui n&#39;est pas consigné le dit (« motif non consigné »). La visite n&#39;écrit rien. Sur une proposition de l&#39;agent dont il a écrit le <strong>parcours</strong>, la visite suit ce parcours : une étape par moment du raisonnement, dans son ordre, avec son titre et sa phrase ; chaque étape montre ses groupes (cartes et sous-groupes compris) et les cartes qu&#39;elle nomme. Le fil pâle du canevas passe alors par ces étapes, numérotées comme le compteur de la visite.</li></ul>",1)),s(r,{name:"ontologie-visite",alt:"La visite guidée à l'étape ⑥ Décisions : la décision mise en avant sur la carte, et dans le cartouche son texte, son motif et l'alternative écartée, barrée"}),e[6]||(e[6]=o('<ul><li><strong>Ajouter</strong> : glissez une icône du dock sur la carte, ou cliquez-la pour poser l&#39;atome au centre de la vue ; il naît <strong>À réviser</strong>. L&#39;outil <strong>Groupe (F)</strong> trace un groupe : glissez sur le fond pour dessiner un rectangle ; les cartes qu&#39;il entoure en font partie, et le déplacer les emporte. Lâché au-dessus d&#39;un groupe, le nouveau groupe en devient un sous-groupe. Quand un groupe est sélectionné, tout élément ajouté depuis le dock y entre, à une place libre, et le groupe reste sélectionné pour le suivant. Un groupe ne touche que la présentation de la carte, ni le schéma ni les versions.</li><li><strong>Créer en liant</strong> : tirez une poignée et lâchez dans le vide ; une petite fenêtre propose les éléments compatibles avec celui dont vous partez (depuis un composant : <strong>réalise → capacité</strong>, <strong>expose → interface</strong>, <strong>persiste → entité</strong>…). Choisissez, nommez, <strong>Créer</strong> : l&#39;élément naît à cet endroit, déjà relié. <strong>⌘Z</strong> retire les deux.</li><li><strong>Lier</strong> : survolez un atome, tirez une de ses quatre poignées vers un autre atome ; pendant le geste, les atomes qui peuvent recevoir le lien s&#39;éclairent, les autres s&#39;estompent. La fenêtre <strong>Nouveau lien</strong> ne propose que les types permis par les règles pour ce couple, sans ceux qui relient déjà les deux atomes ; choisissez la nature, une description, puis <strong>Créer le lien</strong> ; un clic en dehors la ferme.</li><li><strong>Tracer un lien</strong> : sélectionnez-le pour voir ses points de passage ; glissez-les, double-cliquez sur un segment pour en ajouter un, sur un point pour l&#39;enlever ; ses extrémités se re-glissent vers un autre côté. Son <strong>étiquette</strong> se glisse le long du lien, et un peu à côté ; <strong>Recentrer l&#39;étiquette</strong>, au clic droit, la remet à sa place automatique.</li><li><strong>Parcourir l&#39;arbre</strong> : l&#39;arbre défile en lui-même ; ses chevrons déplient un cadre. Choisir une carte la sélectionne, la centre et s&#39;en rapproche un peu ; choisir un cadre le cadre. La carte sélectionnée sur la toile est surlignée dans l&#39;arbre. Après un clic dans l&#39;arbre, au clavier, <strong>↑</strong> et <strong>↓</strong> passent d&#39;une ligne à l&#39;autre et montrent l&#39;élément atteint sur la toile (un groupe atteint se déplie) ; <strong>→</strong> déplie un cadre ou entre dedans, <strong>←</strong> le replie ou remonte au cadre parent ; <strong>Début</strong> et <strong>Fin</strong> vont à la première et à la dernière ligne. Glissez une carte ou un groupe de l&#39;arbre sur un groupe pour l&#39;y rattacher : il y prend une place libre, et le groupe s&#39;agrandit s&#39;il le faut. Le bouton de son en-tête le replie en une fine poignée, et son bord droit se glisse pour l&#39;élargir (200 à 480 px) ; largeur et repli sont retrouvés à la réouverture.</li><li><strong>Chercher</strong> : <strong>⌘F</strong> place le curseur dans <strong>Rechercher…</strong> ; ce que vous tapez filtre aussi l&#39;arbre, qui ne garde que les cartes trouvées et leurs cadres, dépliés ; tapez un nom (sans souci des accents), un identifiant ou une référence du registre. Choisir un résultat sélectionne l&#39;atome, le centre et le rapproche s&#39;il était trop petit pour être lu.</li><li><strong>Trier</strong> : <strong>Filtres</strong> retient une couche, un horizon, un avancement, une révision ou un épic ; <strong>Alertes</strong> › <strong>Avec alerte</strong> ne garde que les atomes qui ont un point à traiter. Chaque cadre porte le nombre de ses alertes (▲).</li><li><strong>Se concentrer, replier</strong> : au clic droit d&#39;un cadre, <strong>Se concentrer sur ce cadre</strong> estompe le reste (la pastille <strong>Concentré</strong> ou <strong>Échap</strong> en sortent) ; le chevron au début du titre, ou <strong>Replier</strong>, réduit le cadre à une barre (« 4 atomes repliés ») où arrivent ses liens ; <strong>Déplier</strong> le rouvre.</li><li><strong>Valider en lot</strong> : <strong>Valider (n)</strong> dans le panneau d&#39;une sélection, <strong>Valider la sélection</strong> au clic droit, ou <strong>Valider les N atomes à réviser</strong> sur un cadre ; une confirmation dit combien d&#39;atomes passent à <strong>Validé</strong>. Un seul <strong>⌘Z</strong> annule le lot.</li><li><strong>Réarranger un cadre</strong> : après un redimensionnement, la carte propose quelques secondes <strong>Réarranger les cartes</strong> ; le même choix est au clic droit du cadre. Les cartes se rangent dans la nouvelle largeur, dans leur ordre de lecture, les cartes reliées côte à côte, et le cadre s&#39;agrandit s&#39;il le faut.</li><li><strong>Le travail derrière un atome</strong> : la carte d&#39;un atome dit « 2 ouverts » quand des épics, stories ou évolutions de son pipe sont en cours ; le panneau les liste sous <strong>Travail au registre</strong>, chacun avec son titre et son état, et <strong>Ouvrir … au Backlog</strong> mène à sa page.</li><li><strong>Ce qui se passe</strong> : chaque action le dit dans un bandeau, en bas — pendant (« Validation de 3 atomes… »), puis le résultat (« 3 atomes validés : … ») avec <strong>Annuler</strong> et <strong>Pourquoi ?</strong>, qui explique ce que l’action a changé ; un échec dit ce qu’il faut faire à la place. <strong>Journal</strong>, dans l’entête, garde toutes les actions de la séance.</li><li><strong>Modifier</strong> : le panneau ne montre que les propriétés du type de l’élément. Un but, un acteur ou une contrainte n’ont ni pipe, ni nature du travail, ni spécification ; une contrainte a sa <strong>source</strong>, une décision sa <strong>décision du registre</strong> et sa <strong>date</strong>, un jalon sa <strong>date</strong> ; les solutions (capacité, composant, module, interface, entité, flux) ont tout — spécification, documents, nature du travail (analyse, conception, code, test, rédaction, recherche, diffusion, exploitation, juridique), pipe, horizon (<strong>Fait</strong> · <strong>Maintenant</strong> · <strong>Ensuite</strong> · <strong>Plus tard</strong>), priorité. Une propriété remplie que le type n’affiche pas est signalée ; <strong>Les retirer</strong> la vide, et <strong>⌘Z</strong> la remet. Rien ne se tape quand cela existe : un document se choisit parmi ceux du projet (ou par <strong>Parcourir…</strong>, dans le dossier du projet seulement) ; un travail se rattache par <strong>Rattacher un travail du registre</strong> (épics, stories, tâches, évolutions, avec leur état) ; une décision se choisit parmi celles du registre. Un document cité qui n’existe plus est signalé en rouge. <strong>Valider</strong> fait passer un atome à <strong>Validé</strong> ; <strong>Repasser à réviser</strong> le ramène à <strong>À réviser</strong>.</li><li><strong>Clic droit</strong> : le menu nomme l&#39;élément visé et range ses actions par intention. Sur un atome : <strong>Consulter</strong> (<strong>Ouvrir le panneau</strong>), <strong>Statut</strong> (<strong>Valider</strong> ou <strong>Repasser à réviser</strong>, <strong>Horizon ▸</strong>), <strong>Disposition</strong> (<strong>Revenir à la palette</strong>), puis <strong>Retirer de la carte</strong>, en rouge. Sur un lien : <strong>Nature ▸</strong>, <strong>Tracé</strong> (<strong>Redresser le lien</strong>, <strong>Recentrer l&#39;étiquette</strong>), <strong>Retirer le lien</strong>. Sur le fond : <strong>Ajouter ici</strong>, une grille d&#39;icônes, <strong>Ajouter ▸</strong> rangé en <strong>Intention</strong>, <strong>Solution</strong> et <strong>Cadre</strong>, <strong>Nouveau groupe ici</strong>, <strong>Tout voir</strong>. Les sous-menus s&#39;ouvrent au survol ou au clic ; les flèches, <strong>Entrée</strong> et <strong>Échap</strong> s&#39;y emploient.</li><li><strong>Raccourcis</strong> : ceux qu&#39;affiche le menu agissent sans lui. Sur l&#39;atome sélectionné : <strong>V</strong> valide (ou repasse à réviser), <strong>1</strong> à <strong>4</strong> fixent l&#39;horizon, <strong>Entrée</strong> ouvre le panneau, <strong>⇧P</strong> revient à la palette, <strong>Suppr</strong> retire. Sur la carte : <strong>G</strong> crée un groupe au centre de la vue, <strong>⇧1</strong> cadre tout. Ils se taisent quand vous écrivez dans un champ.</li><li><strong>Styler</strong> : couleurs d&#39;<strong>Entête</strong>, de <strong>Fond</strong>, de <strong>Bordure</strong> et de <strong>Texte</strong> pour les atomes et les cadres, et la forme de leur bordure : <strong>Trait de bordure</strong> (<strong>Continu</strong>, <strong>Tirets</strong>, <strong>Pointillés</strong>, <strong>Double</strong>) et <strong>Épaisseur</strong> (<strong>Auto</strong>, de 0,5 à 6) ; <strong>Couleur du trait</strong>, <strong>Trait</strong> et <strong>Épaisseur</strong> pour les liens. Un clic sur une pastille ouvre la palette : pastilles proposées, <strong>nuancier</strong>, saisie hexadécimale, et <strong>Demi-teinte</strong>, qui adoucit la couleur choisie (par exemple un fond de la couleur de l&#39;entête, en plus doux). <strong>Revenir à la palette</strong> efface la couleur propre à l&#39;élément.</li><li><strong>Options</strong> : <strong>Options d&#39;affichage</strong>, près du zoom, ouvre le panneau qui règle la carte entière, pour tous. <strong>Lecture</strong> : taille des <strong>Titres</strong> et des <strong>Textes</strong> (S, M, L), <strong>Contraste</strong> normal ou élevé. <strong>Liaisons</strong> : <strong>Courbure</strong> des liens, et <strong>Liens sous les blocs</strong> visibles (on les devine à travers les cartes estompées) ou masqués. <strong>Couleurs</strong> : <strong>Palette</strong> choisit l&#39;habillage de toute la carte — <strong>Défaut</strong>, <strong>Sobre</strong>, <strong>Contraste élevé</strong>, <strong>Pastel</strong>, ou l&#39;une de <strong>Mes palettes</strong> (créées dans Préférences › Apparence), qui est alors copiée dans le projet pour que l&#39;équipe et l&#39;agent la voient ; si vous la modifiez ensuite, <strong>Mettre à jour depuis mes palettes</strong> reprend la nouvelle version. La carte suit le thème clair ou sombre de l&#39;application. Une couleur posée à la main sur un élément prime sur la palette. Chaque réglage s&#39;annule par <strong>⌘Z</strong>, et les exports SVG, PNG et PDF le reprennent.</li></ul><h3 id="ce-que-l-agent-propose" tabindex="-1">Ce que l&#39;agent propose <a class="header-anchor" href="#ce-que-l-agent-propose" aria-label="Permalink to &quot;Ce que l&#39;agent propose&quot;">​</a></h3><p>Quand l&#39;agent propose un changement, la pastille <strong>N propositions de l&#39;agent</strong> apparaît en haut. Un clic passe la carte en <strong>aperçu</strong> : un liseré laiton l&#39;entoure, et une barre flottante dit la proposition — son résumé, puis ce que le lot ferait, en clair (« ajouter 2 couches, 1 atome ; modifier 1 atome »). Sur la carte, rien n&#39;est écrit : ce qui serait ajouté apparaît en pointillés vert, marqué <strong>ajouté</strong> ; ce qui serait modifié est cerclé, marqué <strong>modifié</strong> ; ce qui serait retiré est barré. <strong>Détail</strong> liste chaque changement en une phrase ; les flèches passent d&#39;une proposition à l&#39;autre. <strong>Accepter</strong> fait passer l&#39;ontologie à la version suivante ; <strong>Refuser…</strong> demande un motif ; <strong>Quitter l&#39;aperçu</strong> rend la carte d&#39;aujourd&#39;hui.</p><p>Une proposition qui <strong>détruit</strong> quelque chose — fusionner deux atomes, retirer un atome, un lien ou une couche, sortir une carte d&#39;un de vos groupes — le dit avant tout : un encadré rouge <strong>Ce qui disparaît</strong> liste chaque perte (l&#39;atome, ses liens, ses citations du registre, le groupe que sa carte quitte). Une telle proposition n&#39;est jamais acceptée d&#39;office, même en mode <code>full</code> : <strong>Accepter</strong> demande une confirmation, puis <strong>Accepter quand même</strong>.</p>',4)),s(r,{name:"ontologie-effets",alt:"L'aperçu d'une fusion : l'encadré Ce qui disparaît, et la confirmation demandée avant d'accepter"}),e[7]||(e[7]=o('<h3 id="concevoir-l-architecture" tabindex="-1">Concevoir l&#39;architecture <a class="header-anchor" href="#concevoir-l-architecture" aria-label="Permalink to &quot;Concevoir l&#39;architecture&quot;">​</a></h3><p>Un <strong>composant</strong> porte une <strong>nature technique</strong> — interface utilisateur (écran, fenêtre, popup, formulaire, widget), exécution (service, tâche planifiée, CLI), échanges (API, intégration externe) ou socle (bibliothèque, base de données). Un <strong>module</strong> représente une stack du projet : dans son panneau, <strong>Stack</strong> la choisit dans la liste, ou <strong>Déclarer une stack…</strong> la crée ; l&#39;activité récente de la stack s&#39;y affiche, et un module sans travail rattaché suit l&#39;avancement des composants qu&#39;il contient. Les liens de conception : un composant <strong>réalise</strong> une capacité, un module <strong>contient</strong> des composants (un écran peut contenir des formulaires), un composant <strong>expose</strong> ou <strong>appelle</strong> une interface, <strong>persiste</strong> une entité de données, et une entité en <strong>référence</strong> une autre.</p><h3 id="a-traiter" tabindex="-1">À traiter <a class="header-anchor" href="#a-traiter" aria-label="Permalink to &quot;À traiter&quot;">​</a></h3><p><strong>À traiter</strong> dit chaque point en une phrase, avec le bouton qui le règle : <strong>Passer l&#39;horizon à « Maintenant »</strong> quand l&#39;horizon contredit l&#39;avancement, <strong>Retirer la référence</strong> quand le pipe cite un épic qui n&#39;existe plus, <strong>Rattacher</strong> quand un épic ouvert n&#39;est rattaché à aucun atome (choisissez l&#39;atome, l&#39;épic entre dans son pipe), <strong>Relier à une stack</strong> pour un module qui n&#39;en a pas, <strong>Créer le composant</strong> pour une capacité que rien ne réalise, <strong>Renseigner son pipe</strong> ou <strong>Ouvrir</strong> pour le reste. <strong>Situer</strong> amène l&#39;atome au centre de la carte. Chaque bouton est un geste comme les autres : <strong>⌘Z</strong> l&#39;annule.</p><h3 id="feuille-de-route" tabindex="-1">Feuille de route <a class="header-anchor" href="#feuille-de-route" aria-label="Permalink to &quot;Feuille de route&quot;">​</a></h3><p>La bascule <strong>Carte</strong> · <strong>Feuille de route</strong>, dans l&#39;entête, range les capacités, composants, modules, jalons et buts en <strong>couloirs</strong> : une ligne par couche de la Carte, une colonne par horizon — <strong>Maintenant</strong>, <strong>Ensuite</strong>, <strong>Plus tard</strong>, <strong>Sans horizon</strong> ; <strong>Fait (N)</strong>, repliée à gauche, réunit ce dont l&#39;avancement est fait. On lit « quand » en suivant la ligne, et « dans quel ordre » en descendant une case. Chaque carte a le dessin de la Carte (entête, icône, avancement, travaux ouverts) ; les dépendances sont tracées entre les cartes, en rouge quand elles sont en retard.</p><ul><li><strong>Prioriser</strong> : glissez une carte d&#39;une colonne à l&#39;autre de son couloir pour changer son horizon, ou dans sa case pour changer son rang ; au clavier, <strong>⌥</strong> + flèches. Glisser vers un autre couloir est refusé : la couche se change dans le panneau. Chaque déplacement s&#39;annule par <strong>⌘Z</strong>.</li><li><strong>Demander un arbitrage</strong> dépose la demande : l&#39;agent la voit à sa prochaine lecture de la Carte (et la phrase à lui dire est copiée). Il lit la feuille de route, ses dépendances et le travail ouvert, et propose des mouvements ; il le fait aussi de lui-même quand un couloir n&#39;a plus rien en « maintenant ». La proposition s&#39;ouvre en aperçu sur la feuille de route — chaque carte à sa nouvelle place, avec « venait de … ». Dans <strong>Détail</strong>, un mouvement qui ne vous convient pas se retire (×) ; puis <strong>Accepter</strong> ou <strong>Refuser…</strong>.</li><li><strong>Mise à jour à la fermeture</strong> : quand un épic, une story ou une tâche se ferme (ou qu&#39;une évolution est résolue), ce qui devient fait passe de lui-même à l&#39;horizon <strong>Fait</strong> ; le changement est versé à l&#39;<strong>Historique</strong> (auteur « registre ») et annoncé dans le bandeau.</li><li><strong>Dépendances</strong> : une carte posée plus tôt qu&#39;un élément dont elle dépend le signale (« Dépend de …, prévu plus tard ») ; <strong>Avancer aussi cette dépendance</strong> la ramène dans la même colonne, en un seul geste.</li><li><strong>Créer l&#39;épic</strong> : nommez-le, <strong>Créer</strong> ; l&#39;épic naît au registre, déjà rattaché à l&#39;atome.</li><li><strong>Appliquer au registre</strong> donne aux évolutions ouvertes de chaque carte la priorité de sa colonne (Maintenant 1, Ensuite 2, Plus tard 3), après une confirmation qui liste les changements.</li></ul><h3 id="historique" tabindex="-1">Historique <a class="header-anchor" href="#historique" aria-label="Permalink to &quot;Historique&quot;">​</a></h3><p><strong>Historique</strong> liste les versions, la plus récente d&#39;abord, chacune avec son résumé, son auteur, sa date et son nombre de changements. Un clic sur une version la montre sur la carte : ce qu&#39;elle a changé et qui existe encore est cerclé, ce qui a disparu depuis apparaît en pointillés. <strong>Fermer l&#39;aperçu</strong> rend la carte d&#39;aujourd&#39;hui.</p><p><strong>Exporter</strong> écrit la carte en <strong>SVG</strong>, <strong>PNG</strong>, <strong>PDF</strong> (vectoriel, sur une page A4 ou A3 paysage, avec titre, version et date), <strong>Mermaid</strong> ou <strong>OWL / RDF (Turtle)</strong>.</p><p>Un projet sans ontologie propose <strong>Commencer vide</strong>, ou <strong>Construire depuis le projet</strong> : la carte se construit alors par l&#39;agent, à qui l&#39;écran donne la phrase à dire.</p><h2 id="avec-un-agent-ia" tabindex="-1">Avec un agent IA <a class="header-anchor" href="#avec-un-agent-ia" aria-label="Permalink to &quot;Avec un agent IA&quot;">​</a></h2><p>L&#39;agent lit et propose par les verbes <code>effortless_ontology_*</code> ; il ne modifie jamais le schéma directement, il propose, et il peut ranger la carte — son dernier rangement s&#39;annule ici. C&#39;est aussi lui qui rattache les décisions du registre à l&#39;étape ⑥ : il en retient une poignée de structurantes et vous les propose en un lot, que vous acceptez ou refusez. Voir <a href="/Effortless/agent/ontologie.html">Tenir l&#39;ontologie</a>.</p>',13))])}const b=a(g,[["render",c]]);export{f as __pageData,b as default};
